<template><div class="page"><h2 class="page-title">动态调整</h2><p class="muted">事件只用于审计；当前存款快照是资金事实，不会重复扣减事件金额。</p><div class="card section"><el-form label-position="top"><div class="grid"><el-form-item label="当前有效计划"><el-select v-model="planId" @change="loadExecution"><el-option v-for="p in activePlans" :key="p.id" :label="`Plan v${p.version}`" :value="p.id"/></el-select></el-form-item><el-form-item label="事件类型"><el-select v-model="event.type"><el-option label="计划外支出" value="unplanned_expense"/><el-option label="额外收入" value="extra_income"/><el-option label="收入下降" value="income_decrease"/><el-option label="收入增加" value="income_increase"/><el-option label="目标金额变化" value="goal_amount_change"/><el-option label="目标日期变化" value="goal_date_change"/><el-option label="预算约束变化" value="budget_constraint_change"/></el-select></el-form-item><el-form-item v-if="needsAmount" label="事件金额（元）"><el-input v-model="event.amount"/></el-form-item><el-form-item label="非敏感说明（可选）"><el-input v-model="event.note" maxlength="200"/></el-form-item><el-form-item label="当前存款（元）"><el-input v-model="currentSavings"/></el-form-item><el-form-item label="下一开放周（周一）"><el-date-picker v-model="nextWeek" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="恢复周期"><el-select v-model="horizon"><el-option label="未来2周" :value="2"/><el-option label="未来4周" :value="4"/><el-option label="全部剩余周期" :value="null"/></el-select></el-form-item></div><el-alert v-if="!needsAmount" title="请先在储蓄目标页保存新的目标或约束；此处记录变更原因并生成候选方案。" type="info" :closable="false"/><div class="actions"><el-button @click="recordEvent">记录事件</el-button><el-button type="primary" :loading="loading" @click="preview">重新规划并预览</el-button></div></el-form></div><div class="card section"><div class="actions"><h3 style="flex:1">周度执行偏差</h3><el-button @click="loadExecution">刷新</el-button></div><el-table :data="execution" empty-text="当前计划尚无已发生周"><el-table-column prop="week_start" label="周开始"/><el-table-column label="计划预算"><template #default="s">{{formatMoney(s.row.budget_minor)}}</template></el-table-column><el-table-column label="实际消费"><template #default="s">{{formatMoney(s.row.actual_minor)}}</template></el-table-column><el-table-column label="偏差"><template #default="s">{{formatMoney(s.row.absolute_variance_minor)}}</template></el-table-column><el-table-column label="预算使用率"><template #default="s">{{s.row.percentage_variance_bps==null?'暂无':`${(100+s.row.percentage_variance_bps/100).toFixed(1)}%`}}</template></el-table-column><el-table-column prop="status" label="状态"/></el-table></div><div v-if="candidate" class="card section"><el-result v-if="!candidate.feasible" icon="warning" title="当前条件下原目标已不可行" :sub-title="`最高可达 ${formatMoney(candidate.maximum_achievable_target_minor)}，需要额外收入 ${formatMoney(candidate.required_additional_income_minor)}`"/><template v-else><h3>旧方案 vs 新方案</h3><el-descriptions border :column="3"><el-descriptions-item label="旧未来预算">{{formatMoney(candidate.difference.old_future_budget_minor)}}</el-descriptions-item><el-descriptions-item label="新未来预算">{{formatMoney(candidate.difference.new_future_budget_minor)}}</el-descriptions-item><el-descriptions-item label="预计恢复">{{candidate.recovery_metrics.weeks_to_recover??'无法恢复'}} 周</el-descriptions-item><el-descriptions-item label="旧风险">{{candidate.difference.old_risk_level}}</el-descriptions-item><el-descriptions-item label="新风险">{{candidate.difference.new_risk_level}}</el-descriptions-item><el-descriptions-item label="总调整">{{formatMoney(candidate.difference.total_adjustment_minor)}}</el-descriptions-item></el-descriptions><el-button class="section" type="primary" @click="confirm">确认并激活新计划</el-button></template></div></div></template>
<script setup>
import { computed,onMounted,reactive,ref } from 'vue';import { ElMessage } from 'element-plus';import { api } from '../api/client.js';import { formatMoney,yuanToMinor } from '../utils/money.js'
const plans=ref([]),planId=ref(),event=reactive({type:'unplanned_expense',amount:'500',note:''}),eventIds=ref([]),currentSavings=ref('5000'),nextWeek=ref(''),horizon=ref(4),candidate=ref(),loading=ref(false),execution=ref([]);const activePlans=computed(()=>plans.value.filter(x=>x.is_current));const needsAmount=computed(()=>!['goal_date_change','budget_constraint_change'].includes(event.type))
onMounted(async()=>{plans.value=(await api.get('/budgets')).items;planId.value=activePlans.value[0]?.id;await loadExecution()})
async function loadExecution(){execution.value=planId.value?(await api.get(`/budgets/${planId.value}/execution`)).items:[]}
async function recordEvent(){const p=activePlans.value.find(x=>x.id===planId.value);if(!p)return ElMessage.error('请选择当前计划');try{const r=await api.post('/events',{goal_id:p.goal_id,event_type:event.type,amount_minor:needsAmount.value?yuanToMinor(event.amount):null,event_date:new Date().toISOString().slice(0,10),safe_note:event.note||null});eventIds.value.push(r.id);ElMessage.success('事件已记录')}catch(e){ElMessage.error(e.message)}}
function payload(){return{event_ids:eventIds.value,current_savings_minor:yuanToMinor(currentSavings.value),next_open_week:nextWeek.value,adjustment_mode:'balanced',recovery_horizon_weeks:horizon.value}}
async function preview(){loading.value=true;try{candidate.value=await api.post(`/budgets/${planId.value}/replan-preview`,payload())}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
async function confirm(){try{const r=await api.post(`/budgets/${planId.value}/replans`,payload());ElMessage.success(`Plan ${r.plan_id} 已激活`);candidate.value=null;plans.value=(await api.get('/budgets')).items;planId.value=activePlans.value[0]?.id;await loadExecution()}catch(e){ElMessage.error(e.message)}}
</script>
